-- IPA 2020-06-14 Q53–64: source-reviewed adaptations and exact repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20200614-q53','exam-fe','クリティカルパス','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問53・改編】次の作業ネットワークのクリティカルパスはどれか。矢印上の数字は所要日数。開始→節点1:A(2)、節点1→節点2:B(3)、節点1→節点3:C(3)、節点3→節点2:D(1)、節点2→節点4:E(1)、節点3→節点4:F(3)、節点3→節点5:G(4)、節点4→節点6:H(3)、節点4→節点7:I(2)、節点5→節点7:J(2)、節点6→終了:K(2)、節点7→終了:L(3)。各節点では流入する作業が全て終了してから後続を始める。','[{"id":"a","text":"A→B→E→I→L"},{"id":"b","text":"A→C→D→E→H→K"},{"id":"c","text":"A→C→F→I→L"},{"id":"d","text":"A→C→G→J→L"}]','"d"','選択肢の所要日数は順に11、12、13、14日。最長のA→C→G→J→Lがクリティカルパスである。中文：四条路径分别为11、12、13、14天，最长的A→C→G→J→L是关键路径。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q54','exam-fe','ファンクションポイントによる工数','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問54・改編】新規システムは500FP、開発生産性は1人月当たり10FP。システム導入と開発者教育に合計10人月、プロジェクト管理に開発と導入・教育を合わせた工数の10%を要する。総工数は何人月か。','[{"id":"a","text":"51"},{"id":"b","text":"60"},{"id":"c","text":"65"},{"id":"d","text":"66"}]','"d"','開発は500÷10＝50人月、導入・教育を加え60人月。管理はその10%の6人月なので合計66人月。中文：开发50人月，加导入与培训10人月，再加管理6人月，合计66人月。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q56','exam-fe','サービス可用性','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問56・改編】サービス提供は毎日6～20時、1か月30日。サービス提供時間内の障害停止が7時間、時間外の障害修復が3時間、時間外のメンテナンスが8時間。この月の可用性は何%か。小数第2位を四捨五入する。','[{"id":"a","text":"95.7"},{"id":"b","text":"97.6"},{"id":"c","text":"98.3"},{"id":"d","text":"99.0"}]','"c"','予定提供時間は14×30＝420時間。時間外の修復とメンテナンスは提供時間内停止に含めず、(420−7)÷420×100＝98.3%。中文：计划服务420小时，仅扣除服务时间内停机7小时，可用性约98.3%。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q57','exam-fe','バックアップ媒体の必要本数','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問57・改編】毎月1日にフルバックアップを1本に1回記録し、翌日から次のフルバックアップ前日まで毎日差分を別のテープに追記する。差分テープ1本に1か月分を記録する。常に6か月前の同一日まで各指定日の状態へ復元する。6か月前の月に同じ日がなければその月の末日まで復元できるようにする。この運用に必要なテープは最少何本か。','[{"id":"a","text":"12"},{"id":"b","text":"13"},{"id":"c","text":"14"},{"id":"d","text":"15"}]','"c"','月の途中には当月から6か月前まで7か月分のフルと差分の両方が必要となる場合がある。各月2本なので最大14本。中文：月中可能同时需要本月及往前6个月共7个月的完整备份和差分备份，各一盘，共14盘。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q59','exam-fe','物理セキュリティ監査','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問59・改編】旧JIS Q 27002:2014に基づく物理セキュリティ監査で、指摘すべき状況はどれか。','[{"id":"a","text":"外部からの荷物をサーバ室に立ち入らず受け渡せる場所で受け取る"},{"id":"b","text":"機密性の高い情報資産がある部屋に、許可された人が共通の暗証番号で入る"},{"id":"c","text":"機密性の高い情報資産がある部屋を社外の人の目に触れる場所を避けて設ける"},{"id":"d","text":"取引先との打合せを執務室から分離し、機密資産のない場所で行う"}]','"b"','共通の暗証番号では個人ごとの認証や入退室の追跡が難しく、漏えい時の管理も困難。中文：共用密码难以确认个人身份及追踪出入记录，应作为审计问题。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q60','exam-fe','ユーザ受入テスト監査','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問60・改編】開発委託先から委託元に納品される成果物について、ユーザ受入テストの適切性を確かめる監査の要点はどれか。','[{"id":"a","text":"委託者の計画に従い受託者が受入テストを実施する"},{"id":"b","text":"受託者が成果物と一緒に受入テスト計画書を納品する"},{"id":"c","text":"受託者からの成果物について委託者が要件定義に基づき受入テストを実施する"},{"id":"d","text":"監査人が納品成果物に対する受入テスト計画を策定する"}]','"c"','委託元が要件に照らして成果物を受け入れられるか確認する。監査人は受入作業を代行せず、その適切性を評価する。中文：委托方根据需求验收交付成果；审计人员负责评估验收是否适当。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q64','exam-fe','正味現在価値','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問64・改編】投資効果を正味現在価値（NPV）で比較する。期間3年、割引率5%、単位は万円。Aは投資220、1～3年目の回収額が40・80・120。Bは投資220、回収額が120・80・40。Cは投資220、回収額が80・80・80。投資しない場合は投資・回収とも0。最も投資効果が大きい、又は損失が小さい選択はどれか。','[{"id":"a","text":"A"},{"id":"b","text":"B"},{"id":"c","text":"C"},{"id":"d","text":"投資をしない"}]','"b"','NPVは各年の回収額を(1.05)^年数で割った合計から220を引く。A約−5.68、B約1.40、C約−2.14、投資しない場合0。最大はB。中文：将各年回收额按5%折现后减去投资额，B约为正1.40万元，高于不投资的0。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption');
